def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my_actions = [h[0] for h in history]
    opp_actions = [h[1] for h in history]

    if opp_actions.count('C') == 0:
        return 'D'

    if n >= 99:
        return 'D'

    if n <= 18:
        return 'C'

    if n == 19:
        return 'D'
    if n == 20:
        return 'D'

    first_def_idx = -1
    for i, a in enumerate(my_actions):
        if a == 'D':
            first_def_idx = i
            break

    if first_def_idx == -1:
        return 'C'

    if first_def_idx + 1 < n:
        response = opp_actions[first_def_idx + 1]
        if response == 'D':
            return 'C'

    my_def = my_actions.count('D')
    if my_def / n > 0.15:
        return 'C'

    recent_opp_def = 0
    for a in opp_actions[-5:]:
        if a == 'D':
            recent_opp_def += 1
    if recent_opp_def > 0:
        return 'C'

    last_def_idx = -1
    for i in range(n - 1, -1, -1):
        if my_actions[i] == 'D':
            last_def_idx = i
            break

    if last_def_idx == -1 or (n - last_def_idx) >= 6:
        return 'D'

    return 'C'
